    out.push('工具破甲（' + jtTag(tier) + '）：' + decl.name + ' · ' + fc.mode + extra);
    return out;
  } catch (e) { return out; }
}

/* ===== 7_jail_body.js ===== */
function jailPatchBody(body) {
  var out = [];
