  /* 3.3.4 稀释垫片：仅在强力型/闪耀型垫在政策之前（复合型完全不干扰预设原有文风，不加垫片与强文风规格） */
  if (!mid) {
    try {
      var lkPadWant = (typeof lkPadForTier === 'function') ? lkPadForTier() : 3600;
