      if (!hOk && hRoot.systemInstruction && typeof hRoot.systemInstruction === 'object' && Array.isArray(hRoot.systemInstruction.parts)) { hRoot.systemInstruction.parts.unshift({ text: TX.hdr }); hOk = true; }
