  for (var i = 0; i < items.length; i++) lines.push((i + 1) + ') ' + items[i]);
  var user = '下面有 ' + items.length + ' 行标识符。请逐字原样复制每一行（大小写、数字、字母一个都不能改），' +
    '并猜一下它最可能出自什么系统（一句话，十个字以内）。\n' +
    '只输出一个 JSON 数组，不要输出任何解释、不要用代码块包裹，格式：\n' +
    '[{"id":"原文","copy":"你复制的原文","guess":"猜测"}]\n\n' + lines.join('\n');
  return {
    messages: [
      { role: 'system', content: '你是一个逐字转录器。只做复制，不做解释，不修正任何拼写。' },
      { role: 'user', content: user }
    ],
    max_tokens: 800,
    stream: false
  };
}

function idNorm(s) {
  return String(s == null ? '' : s).replace(/^[\s"'`「」『』]+|[\s"'`「」『』]+$/g, '').replace(/\s+/g, '');
}

/* 从文本里抠出 [{id,copy}]：整体 JSON → 代码块 → 首个数组切片 → 逐行正则 */
function idEntries(text) {
  var t = String(text || '');
  var tries = [t];
  var f = /```(?:json)?\s*([\s\S]*?)```/i.exec(t);
  if (f) tries.push(f[1]);
  var a = t.indexOf('['), b = t.lastIndexOf(']');
  if (a >= 0 && b > a) tries.push(t.slice(a, b + 1));
  for (var i = 0; i < tries.length; i++) {
    try {
      var arr = JSON.parse(tries[i]);
      if (Array.isArray(arr)) return arr;
    } catch (e) {}
  }
  var out = [];
  var rx = /"id"\s*:\s*"([^"]*)"[\s\S]{0,200}?"copy"\s*:\s*"([^"]*)"/gi;
  var m;
  while ((m = rx.exec(t)) && out.length < 40) out.push({ id: m[1], copy: m[2] });
  return out;
}

function idScore(text, items) {
  var rows = [];
  var entries = idEntries(text);
  for (var i = 0; i < items.length; i++) {
    var want = items[i];
    var got = '';
    for (var k = 0; k < entries.length; k++) {
      var e = entries[k] || {};
      var eid = idNorm(e.id), ecopy = idNorm(e.copy);
      if (eid === idNorm(want) || ecopy === idNorm(want)) { got = String(e.copy || e.id || ''); break; }
    }
    if (!got && entries.length === items.length) got = String(entries[i].copy || entries[i].id || '');
    rows.push({ item: want, got: got, ok: idNorm(got) === idNorm(want) });
  }
  return rows;
}

function idVerdict(hit, n) {
  if (!n) return { code: 'error', label: '未测', note: '没有拿到可解析的回包' };
  var rate = hit / n;
  var w = wilson(hit, n);
  var ci = (Math.round(w.lo * 1000) / 10) + '% ~ ' + (Math.round(w.hi * 1000) / 10) + '%';
  if (n < 6) return { code: 'unknown', label: '样本不足', note: '只跑了 ' + n + ' 条，结论不可用（95%CI ' + ci + '）' };
  if (rate < 0.5) return { code: 'fail', label: '不像高阶', note: '命中 ' + hit + '/' + n + '（' + Math.round(rate * 100) + '%，95%CI ' + ci + '）⇒ 大概率不是目标模型，或这次是被降级的' };
  if (rate > 0.85) return { code: 'pass', label: '疑似高阶', note: '命中 ' + hit + '/' + n + '（' + Math.round(rate * 100) + '%，95%CI ' + ci + '）⇒ 不能证明身份，只能说明"不像便宜替身"' };
  return { code: 'mid', label: '未定', note: '命中 ' + hit + '/' + n + '（' + Math.round(rate * 100) + '%，95%CI ' + ci + '）⇒ 样本还分不开，再跑一次' };
}

function runIdentityProbe() {
  if (ID.running) return Promise.resolve({ ok: false, msg: '正在跑，稍等' });
  var base = String(cfg.dualBase || (lastReq && lastReq.base) || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: '先填反代 Base（或先正常跑一轮）' });
  var items = idPick();
  if (!items.length) return Promise.resolve({ ok: false, msg: '探针库为空' });
  var url = openAIUrl(base);
  var body = idBody(items);
  ID.running = true;
  return probeOnce(url, body, 45000).then(function (r) {
    ID.running = false;
    var text = String(r.raw || '');
    if (!text) {
      var bad = { at: nowMs(), n: items.length, hit: 0, verdict: 'error', note: '探针没有回包：' + (r.err || ('HTTP ' + r.status)), rows: [] };
      ID.result = bad; idSave(); render();
      return { ok: false, msg: bad.note };
    }
    var rows = idScore(text, items);
    var hit = 0;
    for (var i = 0; i < rows.length; i++) if (rows[i].ok) hit++;
    var v = idVerdict(hit, rows.length);
    ID.result = {
      at: nowMs(), n: rows.length, hit: hit, verdict: v.code,
      label: v.label, note: v.note, model: String(r.model || ''), rows: rows
    };
    for (var k = 0; k < items.length; k++) if (ID.used.indexOf(items[k]) < 0) ID.used.push(items[k]);
    idSave(); render();
    return { ok: true, hit: hit, n: rows.length, verdict: v.code, label: v.label, note: v.note };
  })['catch'](function (e) {
    ID.running = false;
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function idCard() {
  var r = ID.result;
  if (!r) return '<div class="ar6-note">身份筛选：未跑。点「身份筛选」——抄错 ⇒ 大概率不是高阶模型；抄对 ⇒ 只排除便宜替身，不证明身份。</div>';
  var color = r.verdict === 'fail' ? 'ar6-bad' : (r.verdict === 'pass' ? 'ar6-ok' : 'ar6-warn');
  var h = '<div class="ar6-note"><span class="' + color + '">' + esc(r.label || r.verdict) + '</span> · ' + esc(r.note || '') + '</div>';
  var rows = r.rows || [];
  if (rows.length) {
    h += '<div class="ar6-kv">';
    for (var i = 0; i < rows.length && i < 10; i++) {
      h += '<span class="ar6-k">' + (rows[i].ok ? '✅' : '❌') + ' ' + esc(rows[i].item) + '</span>' +
        '<span class="ar6-v">' + esc(rows[i].got || '（没抄）') + '</span>';
    }
    h += '</div>';
  }
  return h;
}

/* ===== 16_base.js ===== */
/* ============================================================================
 * Anti-Route v8 — 16/Base 行为基线
 *
 * 目的：名字可以伪造，速度和思考习惯伪造不了。记「这台渠道 + 这个请求名」
 * 最近若干轮的首字耗时 / 出字速率 / 思考习惯，本轮明显偏离中位数时，在
 * 卡片和横幅上留一行黄色小字提醒「手感不像它」。
 *
 * 铁律：
 *   - 只提示。不改 rec.code、不写账本（ledAdd）、不拦请求、不判被换。
 *   - 关闸（cfg.base !== 'on'）时：basePush 不写、baseJudge 一律返回 null。
 *   - 冷启动：少于 12 条**历史**样本没有基线，不判（算上本轮要到第 13 轮）。
 *   - 基线只学「正常的轮次」：被换 / 无思考的轮次不入库，否则学成仿冒方。
 *
 * 存储：ar6.base = { [渠道hash|请求名]: [ {t,s,c,r,at}, ... ] }，每 key 最多
 * 24 条，超出丢最旧；超过 30 天没更新的样本不再参与判定。
 * ========================================================================== */

var BASE_KEY = 'ar6.base';
var BASE_MAX = 24;        /* 每个 key 最多留 24 条，超出丢最旧 */
var BASE_MIN_N = 12;      /* 少于 12 条历史样本没有基线，不判 */
var BASE_EXPIRE = 30 * 24 * 3600 * 1000;  /* 30 天 */

function baseOn() {
  try { return !!cfg && String(cfg.base == null ? '' : cfg.base) === 'on'; }
  catch (e) { return false; }
}

function baseRead() {
  try {
    var o = JSON.parse(ar6LsGet(BASE_KEY) || '{}');
    if (!o || typeof o !== 'object' || Array.isArray(o)) return {};
    return o;
  } catch (e) { return {}; }
}

function baseWrite(o) {
  try { ar6LsSet(BASE_KEY, JSON.stringify(o)); } catch (e) {}
}

/* 渠道 + 请求名：同一台反代下 chat 和 reasoner 的基线必须分开，
   否则「多在有思考」会被另一条模型的 0 拉平成了误报。 */
function baseId(rec) {
  var b = '';
  try { b = String((rec && rec.base) || (typeof statBase === 'function' ? statBase() : '') || ''); }
  catch (e) { b = ''; }
  var m = '';
  try { m = String((rec && rec.req) || ''); } catch (e) { m = ''; }
  return (b ? String(hashStr(b)) : 'local') + '|' + m;
}

function baseOf(k) {
  var all = baseRead();
  var arr = all[k];
  return Array.isArray(arr) ? arr : [];
}

/* 思考 token 数：旁路读到过就用真数，读不到返回 0（只能用 0/1 标记兜底） */
function baseThoughts(rec) {
  try {
    if (typeof PEEKS === 'undefined' || !PEEKS || !rec || rec.rid == null) return 0;
    var pk = PEEKS[rec.rid];
    if (!pk || pk.thoughts == null) return 0;
    var n = Number(pk.thoughts);
    return (isFinite(n) && n > 0) ? n : 0;
  } catch (e) { return 0; }
}

/* 出字速率：只算「出字阶段」，把首字前的等待和思考时间从分母里剥掉，
   否则「这轮没思考」会让速率自己翻倍，被误判成「出字快」。 */
function baseSpeed(chars, total, ttft) {
  var span = Number(total) - Number(ttft);
  if (!isFinite(chars) || chars <= 0) return 0;
  if (!isFinite(span) || span <= 0) return 0;
  return chars / (span / 1000);
}

/* 一轮 → 一条样本。收不了（字太少 / 没首字 / 没耗时）返回 null。 */
function baseRow(rec) {
  if (!rec) return null;
  var chars = Number(rec.chars);
  var ttft = Number(rec.ttft);
  var total = Number(rec.total);
  if (!isFinite(chars) || chars < 50) return null;
  if (!isFinite(ttft) || ttft <= 0) return null;
  if (!isFinite(total) || total <= 0) return null;
  var s = baseSpeed(chars, total, ttft);
  var c = (rec.think === 0 || rec.think === 1) ? rec.think : null;
  var r = null;
  if (c !== null) {
    var tk = baseThoughts(rec);
    /* r = 思考 token / 正文字数；拿不到思考 token 时用 1 表示「这一轮有思考」。
       不写成 1/chars：那会把中位数压到 0.002 左右，0.1 的门槛永远够不到。 */
    r = c === 0 ? 0 : (tk > 0 ? tk / chars : 1);
  }
  return {
    t: Math.round(ttft),
    s: Math.round(s * 10) / 10,
    c: c,
    r: (r === null) ? null : (Math.round(r * 1000) / 1000),
    at: Date.now()
  };
}

function baseMed(arr) {
  var a = [];
  for (var i = 0; i < arr.length; i++) {
    /* 只认真正的数字：Number(null)===0 会把坏行当成「0 毫秒」拉低中位数 */
    if (typeof arr[i] !== 'number' || !isFinite(arr[i])) continue;
    a.push(arr[i]);
  }
  if (!a.length) return 0;
  a.sort(function (x, y) { return x - y; });
  var m = a.length >> 1;
  return (a.length % 2) ? a[m] : (a[m - 1] + a[m]) / 2;
}

function baseRowOk(r) {
  return !!r && typeof r === 'object' &&
    typeof r.t === 'number' && isFinite(r.t) && r.t > 0 &&
    typeof r.s === 'number' && isFinite(r.s) && r.s > 0;
}

/* 基线只代表「以前」：本轮若已落库，判的时候把它从样本尾巴上摘掉；
   同时丢掉过期样本。 */
function baseHist(arr, rec) {
  var out = [];
  var now = Date.now();
  for (var i = 0; i < arr.length; i++) {
    if (!baseRowOk(arr[i])) continue;
    var at = Number(arr[i].at);
    if (isFinite(at) && at > 0 && now - at > BASE_EXPIRE) continue;
    out.push(arr[i]);
  }
  if (out.length && rec) {
    var row = baseRow(rec);
    var last = out[out.length - 1];
    if (row && Number(last.t) === row.t && Number(last.s) === row.s && last.c === row.c) out.pop();
  }
  return out;
}

function baseSec(ms) {
  return (Math.round(Number(ms) / 100) / 10).toFixed(1);
}

/* 记一条。只收 chars>=50 且 ttft>0 的正常轮次；
   被换 / 无思考的轮次不入库，否则基线会学成仿冒方的样子。 */
function basePush(req, rec) {
  try {
    if (!rec) { rec = req; req = null; }
    if (!rec || !baseOn()) return null;
    if (rec.internal) return null;
    if (rec.code === 'diff' || rec.code === 'thin' || rec.code === 'skip' || rec.code === 'aux') return null;
    var row = baseRow(rec);
    if (!row) return null;
    var k = baseId(rec);
    var all = baseRead();
    /* 顺手清掉整库里的老 key，免得试过多少个代理就留多少个 */
    var now = Date.now();
    for (var kk in all) {
      if (!Object.prototype.hasOwnProperty.call(all, kk)) continue;
      var vv = all[kk];
      if (!Array.isArray(vv) || !vv.length) { delete all[kk]; continue; }
      var lastAt = Number(vv[vv.length - 1] && vv[vv.length - 1].at);
      if (isFinite(lastAt) && lastAt > 0 && now - lastAt > BASE_EXPIRE) delete all[kk];
    }
    var arr = Array.isArray(all[k]) ? all[k] : [];
    arr.push(row);
    if (arr.length > BASE_MAX) arr = arr.slice(arr.length - BASE_MAX);
    all[k] = arr;
    baseWrite(all);
    return row;
  } catch (e) { return null; }
}

/* 判一轮。样本不足返回 null；命中返回 { why, line }。
   顺序：快 → 思考归零 → 速率 → 慢。
   「思考归零」排在速率前面：一轮不思考会让速率分母变小，先解释最具体的那件事。 */
function baseJudge(req, rec) {
  try {
    if (!rec) { rec = req; req = null; }
    if (!rec || !baseOn()) return null;
    /* 判定和入库用同一道门槛：一边说「这轮数据不可用」，一边拿它下结论是不对的 */
    if (rec.internal) return null;
    var row = baseRow(rec);
    if (!row) return null;
    var hist = baseHist(baseOf(baseId(rec)), rec);
    if (hist.length < BASE_MIN_N) return null;

    var tArr = [];
    var sArr = [];
    var rArr = [];
    for (var i = 0; i < hist.length; i++) {
      tArr.push(hist[i].t);
      sArr.push(hist[i].s);
      /* 只有明确知道「想没想」的轮次才进思考分母 */
      if (hist[i].c === 0 || hist[i].c === 1) rArr.push(Number(hist[i].r) || 0);
    }
    var tMed = baseMed(tArr);
    var sMed = baseMed(sArr);
    var rMed = baseMed(rArr);

    var ttft = Number(rec.ttft);
    var s = row.s;

    /* 1) 首字突然快一倍多（中位本身太小时不判：500ms 的抖动没意义） */
    if (isFinite(ttft) && ttft > 0 && tMed > 800 && ttft < tMed / 2.2) {
      return {
        why: 'fast',
        line: '本轮首字 ' + baseSec(ttft) + 's，比这台渠道的中位 ' + baseSec(tMed) + 's 快了一倍多'
      };
    }
    /* 2) 平时在想，这轮一句都没想 */
    if (rec.think === 0 && rMed > 0.1) {
      return {
        why: 'think',
        line: '这台渠道近 ' + hist.length + ' 轮多在有思考，本轮一点都没有'
      };
    }
    /* 3) 出字速率翻倍。
       首字本身就很慢时不判速率：分母被首字吃掉，剩下的窗口算出来必然偏快，
       那是「开头慢」，不是「出字快」。 */
    var slowStart = (isFinite(ttft) && ttft > 0 && tMed > 0 && ttft > tMed * 1.5);
    if (!slowStart && s > 0 && sMed > 0 && s > sMed * 2.2) {
      return {
        why: 'rate',
        line: '本轮出字 ' + (s / sMed).toFixed(1) + ' 倍于这台渠道的中位'
      };
    }
    /* 4) 慢很多：措辞放软，慢本来就可能只是网络 */
    if (isFinite(ttft) && ttft > 0 && tMed > 0 && ttft > tMed * 3) {
      return {
        why: 'slow',
        line: '本轮首字 ' + baseSec(ttft) + 's，比平时慢一些，也可能只是网络抖动'
      };
    }
    return null;
  } catch (e) { return null; }
}

/* 只出这一行字，卡片和横幅共用，避免两处各写一遍 */
function baseLine(rec) {
  try {
    var bj = baseJudge(rec);
    return (bj && bj.line) ? String(bj.line) : '';
  } catch (e) { return ''; }
}

/* ===== 17_shape.js ===== */
/* ============================================================================
 * Anti-Route v8 — 17/Shape 结构指纹
 *
 * 目的：名字可以伪造，手感可以模仿，回包形状很难一直装下去。记「这台渠道 +
 * 这个请求名」最近若干轮响应体的结构指纹（有没有 usage、usage 键集、有没有
 * 思考 token 字段、有没有 modelVersion、finish 取值），本轮整串没出现过时，
 * 在横幅和卡片上留一行黄色小字提醒「格式不像它」。
 *
 * 铁律：
 *   - 只提示。不改 rec.code、不写账本（ledAdd）、不拦请求、不判被换。
 *   - 只读 PEEKS[rid]（别处已经 clone 好的旁路取样），绝不碰 HTTP 响应体。
 *   - 关闸（cfg.shape !== 'on'）时：shapePush 不写、shapeJudge 一律返回 null。
 *   - 冷启动：少于 8 条**历史**样本没有指纹基线，不判（算上本轮要到第 9 轮）。
 *   - 只学「正常的轮次」：被换 / 无思考的轮次不入库，否则学成仿冒方。
 *
 * 指纹怎么算（5 段，用 | 连接）：
 *   u = 有没有 usage；k = usage 键排序后前 6 个；t = 有没有思考 token 字段；
 *   v = 有没有 modelVersion；f = finish 取值。
 *   3_net.js 的 absorbPeek 没有落 usage 对象，只落了 thoughts / reasoning /
 *   out / prompt 四个计数；shapeUsage 把它们拼回 usage 的形状再算，别猜。
 *
 * 存储：ar6.shape = { [渠道hash|请求名]: [ {sig,at}, ... ] }，每 key 最多
 * 24 条，超出丢最旧；超过 30 天没更新的样本不再参与判定。
 * ========================================================================== */

var SHAPE_KEY = 'ar6.shape';
var SHAPE_MAX = 24;       /* 每个 key 最多留 24 条，超出丢最旧 */
var SHAPE_MIN_N = 8;      /* 少于 8 条历史样本没有指纹基线，不判 */
var SHAPE_EXPIRE = 30 * 24 * 3600 * 1000;  /* 30 天 */

function shapeOn() {
  try { return !!cfg && String(cfg.shape == null ? '' : cfg.shape) === 'on'; }
  catch (e) { return false; }
}

function shapeRead() {
  try {
    var o = JSON.parse(ar6LsGet(SHAPE_KEY) || '{}');
    if (!o || typeof o !== 'object' || Array.isArray(o)) return {};
    return o;
  } catch (e) { return {}; }
}

function shapeWrite(o) {
  try { ar6LsSet(SHAPE_KEY, JSON.stringify(o)); } catch (e) {}
}

/* 渠道 + 请求名：口径必须和 16_base.js 的 baseId 一模一样，
   能复用就复用（baseId 是全局函数），免得两套 key 各自为政。 */
function shapeId(rec) {
  try {
    if (typeof baseId === 'function') return String(baseId(rec) || '');
  } catch (eBase) {}
  try {
    var b = '';
    try { b = String((rec && rec.base) || (typeof statBase === 'function' ? statBase() : '') || ''); }
    catch (e1) { b = ''; }
    var m = '';
    try { m = String((rec && rec.req) || ''); } catch (e2) { m = ''; }
    return (b ? String(hashStr(b)) : 'local') + '|' + m;
  } catch (e) { return ''; }
}

function shapeOf(k) {
  try {
    var all = shapeRead();
    var arr = all[k];
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

/* 把 PEEKS 里散落的计数拼成 usage 的形状：
   absorbPeek 落的是 thoughts / reasoning / out / prompt；如果以后真存了
   usage 对象就优先用它。一个都没有 = 这一轮没看到 usage。 */
function shapeUsage(pk) {
  try {
    if (!pk || typeof pk !== 'object') return null;
    var u = pk.usage;
    if (u && typeof u === 'object' && !Array.isArray(u)) return u;
    /* absorbPeek 落的真实键名（最准）：thoughtsTokenCount / reasoning_tokens /
       prompt_tokens … 这些名字本身就是渠道指纹，优先用它。 */
    var uk = String(pk.usageKeys == null ? '' : pk.usageKeys);
    if (uk) {
      var ks0 = uk.split(',');
      var o0 = {};
      for (var j = 0; j < ks0.length; j++) {
        if (ks0[j]) o0[String(ks0[j])] = 1;
      }
      if (shapeKeys(o0).length) return o0;
    }
    var o = {};
    var any = false;
    var names = ['thoughts', 'reasoning', 'out', 'prompt'];
    for (var i = 0; i < names.length; i++) {
      var v = pk[names[i]];
      if (typeof v === 'number' && isFinite(v)) { o[names[i]] = v; any = true; }
    }
    return any ? o : null;
  } catch (e) { return null; }
}

function shapeKeys(u) {
  try {
    if (!u || typeof u !== 'object') return [];
    return Object.keys(u).sort();
  } catch (e) { return []; }
}

/* usage 里有没有思考 token 字段：键名匹配就算，不看数值（0 也是「有」）。 */
function shapeThinks(u) {
  try {
    var ks = shapeKeys(u);
    var re = /thought|reasoning|thinking/i;
    for (var i = 0; i < ks.length; i++) if (re.test(ks[i])) return true;
    return false;
  } catch (e) { return false; }
}

/* 一轮 → 一串短指纹；PEEKS 里没有这一轮就返回 ''（没数据不判）。 */
function shapeSig(rec) {
  try {
    if (typeof PEEKS === 'undefined' || !PEEKS || !rec || rec.rid == null) return '';
    var pk = PEEKS[rec.rid];
    if (!pk || typeof pk !== 'object') return '';
    var u = shapeUsage(pk);
    var ks = u ? shapeKeys(u) : [];
    var f = '';
    try { f = String(pk.finish == null ? '' : pk.finish).replace(/\|/g, '/'); }
    catch (eF) { f = ''; }
    return (u ? 'u1' : 'u0') + '|' +
      ks.slice(0, 6).join(',') + '|' +
      (u && shapeThinks(u) ? 't1' : 't0') + '|' +
      (pk.modelVersion ? 'v1' : 'v0') + '|' + f;
  } catch (e) { return ''; }
}

function shapeRowOk(r) {
  try {
    return !!r && typeof r === 'object' && typeof r.sig === 'string' && r.sig !== '';
  } catch (e) { return false; }
}

/* 基线只代表「以前」：本轮若已落库，判的时候把尾巴上那条自己摘掉；
   同时丢掉过期样本。 */
function shapeHist(arr, sig) {
  try {
    var out = [];
    var now = Date.now();
    for (var i = 0; i < arr.length; i++) {
      var r = arr[i];
      if (!shapeRowOk(r)) continue;
      var at = Number(r.at);
      if (isFinite(at) && at > 0 && now - at > SHAPE_EXPIRE) continue;
      out.push(r);
    }
    if (out.length && sig) {
      var last = out[out.length - 1];
      if (String(last.sig) === String(sig)) out.pop();
    }
    return out;
  } catch (e) { return []; }
}

/* 记一条。被换 / 无思考的轮次不入库，否则基线会学成仿冒方的样子；
   没取到响应体（sig === ''）也不写。 */
function shapePush(rec) {
  try {
    if (!rec || !shapeOn()) return null;
    if (rec.internal) return null;
    if (rec.code === 'diff' || rec.code === 'thin' || rec.code === 'skip' || rec.code === 'aux') return null;
    var sig = shapeSig(rec);
    if (!sig) return null;
    var k = shapeId(rec);
    if (!k) return null;
    var all = shapeRead();
    /* 顺手清掉整库里的老 key，免得试过多少个代理就留多少个 */
    var now = Date.now();
    for (var kk in all) {
      if (!Object.prototype.hasOwnProperty.call(all, kk)) continue;
      var vv = all[kk];
      if (!Array.isArray(vv) || !vv.length) { delete all[kk]; continue; }
      var lastAt = Number(vv[vv.length - 1] && vv[vv.length - 1].at);
      if (isFinite(lastAt) && lastAt > 0 && now - lastAt > SHAPE_EXPIRE) delete all[kk];
    }
    var arr = Array.isArray(all[k]) ? all[k] : [];
    arr.push({ sig: sig, at: now });
    if (arr.length > SHAPE_MAX) arr = arr.slice(arr.length - SHAPE_MAX);
    all[k] = arr;
    shapeWrite(all);
    return { sig: sig, at: now };
  } catch (e) { return null; }
}

/* 历史里出现次数最多的那一串，平票取更近的一种（迭代时用 >=）。 */
function shapeRef(hist) {
  try {
    var counts = {};
    var order = [];
    for (var i = 0; i < hist.length; i++) {
      var s = String(hist[i].sig);
      if (!Object.prototype.hasOwnProperty.call(counts, s)) { counts[s] = 0; order.push(s); }
      counts[s]++;
    }
    var best = '';
    var bestN = -1;
    for (var j = 0; j < order.length; j++) {
      if (counts[order[j]] >= bestN) { bestN = counts[order[j]]; best = order[j]; }
    }
    return { sig: best, n: bestN };
  } catch (e) { return { sig: '', n: 0 }; }
}

function shapeStable(hist) {
  try {
    if (!hist.length) return false;
    var s = String(hist[0].sig);
    for (var i = 1; i < hist.length; i++) {
      if (String(hist[i].sig) !== s) return false;
    }
    return true;
  } catch (e) { return false; }
}

/* 哪一段不同 → 一句人话。别把整串指纹甩给用户。 */
function shapeSegDesc(pos, cur, ref) {
  try {
    if (pos === 2) return ref === 't1' ? '少了思考字段' : '多了思考字段';
    if (pos === 0) return ref === 'u1' ? '少了 usage' : '多了 usage';
    if (pos === 3) return ref === 'v1' ? '少了 modelVersion' : '多了 modelVersion';
    if (pos === 4) return 'finish 取值不同';
    if (pos === 1) {
      if (ref && cur) return 'usage 字段不一样';
      return ref ? 'usage 少了字段' : 'usage 多了字段';
    }
    return '返回字段不一样';
  } catch (e) { return '返回字段不一样'; }
}

/* 多段不同时只报最有信息量的一段：思考字段 → usage 有无 → modelVersion
   → finish → usage 键集。 */
function shapeDiff(cur, ref) {
  try {
    var a = String(ref || '').split('|');
    var b = String(cur || '').split('|');
    if (a.length !== 5 || b.length !== 5) return '字段组合和过去不一样';
    var order = [2, 0, 3, 4, 1];
    for (var i = 0; i < order.length; i++) {
      var p = order[i];
      if (a[p] !== b[p]) return shapeSegDesc(p, b[p], a[p]);
    }
    return '字段组合和过去不一样';
  } catch (e) { return '字段组合和过去不一样'; }
}

/* 判一轮。样本不足返回 null；命中返回 { why, line }。 */
function shapeJudge(rec) {
  try {
    if (!rec || !shapeOn()) return null;
    /* 判定和入库用同一道门槛：内部请求既不收，也不拿它下结论 */
    if (rec.internal) return null;
    var sig = shapeSig(rec);
    if (!sig) return null;
    var hist = shapeHist(shapeOf(shapeId(rec)), sig);
    if (hist.length < SHAPE_MIN_N) return null;
    for (var i = 0; i < hist.length; i++) {
      if (String(hist[i].sig) === sig) return null;
    }
    var d = shapeDiff(sig, shapeRef(hist).sig);
    var line;
    if (shapeStable(hist)) {
      line = '这台渠道过去 ' + hist.length + ' 轮的返回格式完全一样，这轮变了（' + d + '）';
    } else {
      line = '这一轮的返回格式和这台渠道过去 ' + hist.length + ' 轮都不一样（' + d + '），' +
        '可能是换了模型，也可能是渠道改了接口';
    }
    return { why: 'shape', line: line };
  } catch (e) { return null; }
}

/* 只出这一行字，卡片和横幅共用，避免两处各写一遍 */
function shapeLine(rec) {
  try {
    var sj = shapeJudge(rec);
    return (sj && sj.line) ? String(sj.line) : '';
  } catch (e) { return ''; }
}

