    wandBtn.addEventListener('click', doFire);
  }
  if (skipBtn) {
    skipBtn.addEventListener('pointerup', doSkip);
    skipBtn.addEventListener('click', doSkip);
  }
  ov.addEventListener('click', function (ev) {
    if (fired) return;
    if (ev && ev.target === ov) doSkip(ev);
  });

  return true;
}

