function pvpSleep(ms) {
  return new Promise(function (resolve) { setTimeout(resolve, Math.max(pvpGapMs(), ms || 0)); });
}

function pvpSpend(code, why) {
  var t = nowMs();
  PVP.try++;
  PVP.win.push(t);
  PVP.lastCode = Number(code || 0);
  PVP.lastNote = String(why || '');
  PVP.lastAt = t;
  PVP.round.tries++;
  PVP.round.last = PVP.lastNote;
  pvpPurgeWin(t);
