function pvpWhy(why) {
  if (why === 'max') return '这一轮已经重试过一次了';
  if (why === 'turn') return '这一轮已经补过一次，不重复补';
  if (why === 'gap') return '刚试过，等一下再试';
  if (why === 'rate') return '一分钟内补太多次了，先停手';
  if (why === 'lock') return '上一次还没走完';
  return '现在重试不了（' + why + '）';
}

