/* 跨 SSE 分片有状态标签状态机：实时拆分流式思考与正文，支持半截标签跨帧拼接、预开思考标签 initialTag 与孤立闭标签自动回溯纠偏 */
function ar6CreateTagSplitter(opts) {
  var initTag = (opts && opts.initialTag) ? String(opts.initialTag).toLowerCase() : '';
  var inTag = initTag;
  var sawOpen = !!initTag;
  var preOpenBodyChars = 0;
  var pending = '';
  var MAX_HOLD = 40;

  function stripWrap(s) {
    return s ? s.replace(AR6_BODY_WRAP_RE, '') : '';
  }

  function findClose(buf, tag) {
    if (tag === '<!--') {
      var ci = buf.indexOf('-->');
      return ci >= 0 ? { idx: ci, end: ci + 3 } : null;
    }
    var escTag = tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var rx = new RegExp('<\\/' + escTag + '\\s*>', 'i');
    var m = rx.exec(buf);
    return m ? { idx: m.index, end: m.index + m[0].length } : null;
  }

