    var lt = buf.lastIndexOf('<');
    if (!isInside) {
      if (lt >= 0 && buf.length - lt <= MAX_HOLD && buf.indexOf('>', lt) < 0) return lt;
      return buf.length;
    }
    if (inTag === '<!--') {
      var d = buf.lastIndexOf('-');
