          if (preOpenBodyChars > 0) {
            retroBodyToThink += preOpenBodyChars;
            preOpenBodyChars = 0;
          }
          if (orphanCm.index > 0) outThink += buf.slice(0, orphanCm.index);
          sawOpen = true;
          buf = buf.slice(orphanCm.index + orphanCm[0].length);
