        if (!om) {
          var cut = isFlush ? buf.length : holdTailIndex(buf, false);
          var bPiece = stripWrap(buf.slice(0, cut));
          outBody += bPiece;
          if (!sawOpen && bPiece) preOpenBodyChars += bPiece.length;
          pending = buf.slice(cut);
          break;
        }
        if (om.index > 0) {
          var bPre = stripWrap(buf.slice(0, om.index));
