      DOCK_DRAG_AT = Date.now();
      var p = dockSnapPos(Number(ev && ev.clientX) || sx, Number(ev && ev.clientY) || sy,
        Number(HOST.innerWidth) || 360, Number(HOST.innerHeight) || 640);
      cfg.dockSide = p[0]; cfg.dockY = p[1];
      try { saveCfg(); } catch (e2) {}
      try { render(); } catch (e3) {}
    }
