  if (act === 'dock-open') {
    if (DOCK_DRAG_AT && Date.now() - DOCK_DRAG_AT < 600) { DOCK_DRAG_AT = 0; return; }
    minimized = false;
    cfg.min = false;
    cfg.docked = false;
    saveCfg();
    render();
