    var linkU = (typeof UPD_RT !== 'undefined' && UPD_RT && UPD_RT.fallbackUrl) || (stL && stL.pkgUrl) || ((typeof updDefaultPkgUrl === 'function') ? updDefaultPkgUrl() : '');
    if (linkU) copyTo(linkU, '新版直链');
