    try {
      runAliasSweep().then(function (r) {
        banner((r && r.msg) ? r.msg : '别名扫描已完成', (r && r.ok) ? 'ok' : 'warn', true);
        render();
      });
    } catch (ePA) { banner('别名扫描未启动：' + String(ePA && ePA.message || ePA), 'warn', true); }
