  if (act === 'diagcheck') {
    try { DET.tries++; installFetchHook(); try { bindStEvents(); } catch (eSB) {} try { installXhrDetect(); } catch (eXD2) {} } catch (eCH) {}
    var stPass = 0, stTotal = 0, stFails = [];
