        ? ('护盾自检完成：' + stPass + '/' + stTotal + ' 项通过 · 挂钩 ' + DET.wins + ' 个窗口' + (stFails.length ? ('（异常：' + stFails.slice(0, 2).join('、') + '）') : ''))
