      var whyG = gT.why === 'max' ? ('本轮已经补过 ' + RS.trunc.count + ' 次了')
        : (gT.why === 'turn' ? '这一轮已经补过一次，不重复补' : ('现在补不了（' + gT.why + '）'));
      banner('✂️ ' + whyG, 'warn');
      return;
    }
